#include <iostream>

struct Sophuc {
    float thuc;
    float ao;
};

Sophuc Cong(Sophuc x, Sophuc y) {
    Sophuc kq;
    kq.thuc = x.thuc + y.thuc;
    kq.ao = x.ao + y.ao;
    return kq;
}

Sophuc Tru(Sophuc x, Sophuc y) {
    Sophuc kq;
    kq.thuc = x.thuc - y.thuc;
    kq.ao = x.ao - y.ao;
    return kq;
}

void In(Sophuc x) {
    std::cout << "(" << x.thuc << "," << x.ao << ")" << std::endl;
}

int main() {
    Sophuc x, y;
    if (std::cin >> x.thuc >> x.ao >> y.thuc >> y.ao) {
        std::cout << "x + y = "; In(Cong(x, y));
        std::cout << "x - y = "; In(Tru(x, y));
    }
    return 0;
}

#include <iostream>
#include <string>
#include <vector>

struct Sinhvien {
    std::string hoten;
    float diem;
};

// Returns a reference to the student with the highest score
const Sinhvien& timSvMax(const std::vector<Sinhvien>& ds) {
    size_t kmax = 0;
    for (size_t i = 1; i < ds.size(); ++i) {
        if (ds[i].diem > ds[kmax].diem) {
            kmax = i;
        }
    }
    return ds[kmax];
}

void inSinhvien(const Sinhvien& sv) {
    std::cout << sv.hoten << "\t" << sv.diem << std::endl;
}

int main() {
    // A clean modern equivalent demonstrating safe reference return
    std::vector<Sinhvien> lop = {
        {"An", 7.5f},
        {"Binh", 9.0f},
        {"Chi", 8.5f}
    };

    for (const auto& sv : lop) {
        inSinhvien(sv);
    }

    const Sinhvien& b = timSvMax(lop);
    std::cout << "Max: ";
    inSinhvien(b);

    return 0;
}

#include <iostream>

struct NgayThangCompact {
    unsigned int ngay : 5;     // 1..31 (5 bits can hold 0..31)
    unsigned int thang : 4;    // 1..12 (4 bits can hold 0..15)
    unsigned int gioitinh : 1; // 0: Nu, 1: Nam (1 bit holds 0..1)
    unsigned int nam : 12;     // 0..4095 (12 bits can hold years up to 4095)
};

int main() {
    NgayThangCompact d;
    d.ngay = 25;
    d.thang = 12;
    d.gioitinh = 1;
    d.nam = 2024;

    std::cout << "Ngay: " << d.ngay << "/" << d.thang << "/" << d.nam << std::endl;
    std::cout << "Gioi tinh (1=Nam, 0=Nu): " << d.gioitinh << std::endl;
    std::cout << "Kich thuoc struct (bytes): " << sizeof(NgayThangCompact) << std::endl;

    return 0;
}
